package unit

// Signing secret of a generic webhook integration (RFC-122): generated by
// the platform, shown once, stored only encrypted, rotated with a 24 hour
// overlap, and confined to the tenant's own webhook integrations.

import (
	"context"
	"errors"
	"strings"
	"testing"
	"time"

	"github.com/openctemio/openctem/api/pkg/crypto"
	"github.com/openctemio/openctem/api/pkg/domain/integration"
	"github.com/openctemio/openctem/api/pkg/domain/shared"
	"github.com/openctemio/openctem/api/pkg/webhooksig"
)

func TestWebhookSigningSecret_RotateWithOverlap(t *testing.T) {
	repo := newMockIntegrationRepo()
	cipher, err := crypto.NewCipher(make([]byte, 32))
	if err != nil {
		t.Fatal(err)
	}
	svc := newTestIntegrationService(repo, newMockSCMExtRepo(), cipher)
	tenantID := shared.NewID()
	hook := integration.NewIntegration(shared.NewID(), tenantID, "SIEM", integration.CategoryNotification, integration.ProviderWebhook, integration.AuthTypeToken)
	repo.integrations[hook.ID()] = hook
	ctx := context.Background()

	st, err := svc.WebhookSigningStatus(ctx, tenantID, hook.ID())
	if err != nil || st.Configured {
		t.Fatalf("fresh integration: %+v %v", st, err)
	}

	first, err := svc.RotateWebhookSigningSecret(ctx, tenantID, hook.ID())
	if err != nil {
		t.Fatal(err)
	}
	if _, err := webhooksig.ParseSecret(first.Secret); err != nil || first.PreviousValidUntil != nil {
		t.Fatalf("first rotation: %q overlap %v err %v", first.Secret, first.PreviousValidUntil, err)
	}
	stored, _ := hook.Metadata()[integration.MetaSigningSecret].(string)
	if stored == "" || strings.Contains(stored, first.Secret) {
		t.Fatalf("secret not stored encrypted: %q", stored)
	}

	second, err := svc.RotateWebhookSigningSecret(ctx, tenantID, hook.ID())
	if err != nil {
		t.Fatal(err)
	}
	if second.PreviousValidUntil == nil || second.PreviousValidUntil.Sub(second.RotatedAt) != integration.SigningSecretOverlap {
		t.Fatalf("second rotation overlap %v", second.PreviousValidUntil)
	}
	now := time.Now()
	secrets, err := integration.SigningSecrets(hook.Metadata(), cipher.DecryptString, now)
	if err != nil || len(secrets) != 2 || secrets[0] != second.Secret || secrets[1] != first.Secret {
		t.Fatalf("during overlap: %d secrets, err %v", len(secrets), err)
	}
	after, _ := integration.SigningSecrets(hook.Metadata(), cipher.DecryptString, now.Add(25*time.Hour))
	if len(after) != 1 || after[0] != second.Secret {
		t.Fatalf("after overlap: %d secrets", len(after))
	}

	// A rotation inside the overlap drops the oldest secret at once: at most
	// two secrets ever sign.
	third, err := svc.RotateWebhookSigningSecret(ctx, tenantID, hook.ID())
	if err != nil {
		t.Fatal(err)
	}
	secrets, _ = integration.SigningSecrets(hook.Metadata(), cipher.DecryptString, now)
	if len(secrets) != 2 || secrets[0] != third.Secret || secrets[1] != second.Secret {
		t.Fatalf("third rotation keeps %d secrets", len(secrets))
	}
	for _, s := range secrets {
		if s == first.Secret {
			t.Fatal("the first secret still signs after two rotations")
		}
	}

	st, _ = svc.WebhookSigningStatus(ctx, tenantID, hook.ID())
	if !st.Configured || st.RotatedAt == nil || st.PreviousValidUntil == nil {
		t.Fatalf("status %+v", st)
	}
}

func TestWebhookSigningSecret_OtherTenantOrProviderNotFound(t *testing.T) {
	repo := newMockIntegrationRepo()
	svc := newTestIntegrationService(repo, newMockSCMExtRepo(), crypto.NewNoOpEncryptor())
	tenantID := shared.NewID()
	slack := integration.NewIntegration(shared.NewID(), tenantID, "Slack", integration.CategoryNotification, integration.ProviderSlack, integration.AuthTypeToken)
	hook := integration.NewIntegration(shared.NewID(), tenantID, "SIEM", integration.CategoryNotification, integration.ProviderWebhook, integration.AuthTypeToken)
	repo.integrations[slack.ID()] = slack
	repo.integrations[hook.ID()] = hook
	ctx := context.Background()

	if _, err := svc.RotateWebhookSigningSecret(ctx, tenantID, slack.ID()); !errors.Is(err, shared.ErrNotFound) {
		t.Errorf("Slack integration: want not found, got %v", err)
	}
	if _, err := svc.RotateWebhookSigningSecret(ctx, shared.NewID(), hook.ID()); !errors.Is(err, shared.ErrNotFound) {
		t.Errorf("another tenant: want not found, got %v", err)
	}
	if _, err := svc.WebhookSigningStatus(ctx, shared.NewID(), hook.ID()); !errors.Is(err, shared.ErrNotFound) {
		t.Errorf("another tenant's status: want not found, got %v", err)
	}
	if _, ok := hook.Metadata()[integration.MetaSigningSecret]; ok {
		t.Fatal("a refused rotation stored a secret")
	}
}

// A stored secret that does not decrypt fails the delivery instead of
// sending it unsigned.
func TestSigningSecrets_UnreadableFailsClosed(t *testing.T) {
	meta := map[string]any{integration.MetaSigningSecret: "garbage"}
	_, err := integration.SigningSecrets(meta, func(string) (string, error) { return "", errors.New("bad key") }, time.Now())
	if !errors.Is(err, integration.ErrSigningSecretUnreadable) {
		t.Fatalf("want ErrSigningSecretUnreadable, got %v", err)
	}
	if s, err := integration.SigningSecrets(map[string]any{}, nil, time.Now()); err != nil || s != nil {
		t.Fatalf("no secret: %v %v", s, err)
	}
}
